import { EMPTY_LM_PARAMETERS } from '@/01-models/types';
import type { ChatGroupRecipe } from '@/features/recipes/logic/recipe';
import {
  XIcon, GlobeIcon,
  DatabaseIcon, Settings2Icon, BookmarkPlusIcon,
  CpuIcon, InfoIcon,
  ChefHatIcon,
  DownloadIcon, BrainCircuitIcon,
  FolderIcon,
  FileIcon, WrenchIcon,
